class Solution:
    def new21Game(self, n: int, k: int, maxPts: int) -> float:
        if k == 0:
            return 1.0
        dp = [0.0] * (n + 1)
        dp[0] = 1.0
        for i in range(1, n + 1):
            lo = max(0, i - maxPts)
            hi = min(i - 1, k - 1)
            s = sum(dp[lo:hi + 1])
            dp[i] = s / maxPts
        return sum(dp[k:n + 1])

