class Solution {
public:
    double new21Game(int n, int k, int maxPts) {
        if (k == 0) return 1.0;
        vector<double> dp(n + 1, 0.0);
        dp[0] = 1.0;
        for (int i = 1; i <= n; ++i) {
            int lo = max(0, i - maxPts), hi = min(i - 1, k - 1);
            double s = 0;
            for (int j = lo; j <= hi; ++j) s += dp[j];
            dp[i] = s / maxPts;
        }
        double ans = 0;
        for (int i = k; i <= n; ++i) ans += dp[i];
        return ans;
    }
};

