class Solution:
    def new21Game(self, n: int, k: int, maxPts: int) -> float:
        if k == 0:
            return 1.0
        dp = [0.0] * (n + 1)
        dp[0] = 1.0
        wsum = 1.0
        for i in range(1, n + 1):
            dp[i] = wsum / maxPts
            if i < k:
                wsum += dp[i]
            if i - maxPts >= 0:
                wsum -= dp[i - maxPts]
        return sum(dp[k:n + 1])

